#include <bits/stdc++.h>
using namespace std;
// Race condition WITHOUT a data race: every access is locked,
// but check-then-act is not one atomic step.
int main() {
    int balance = 100;
    mutex m;
    latch bothChecked(2);              // forces the bad interleaving
    auto withdraw = [&](int amt) {
        bool ok;
        { lock_guard<mutex> g(m); ok = balance >= amt; }   // check
        bothChecked.arrive_and_wait(); // both threads checked first
        if (ok) { lock_guard<mutex> g(m); balance -= amt; } // act
    };
    cout << "start balance = " << balance << "\n";
    thread a(withdraw, 80), b(withdraw, 80);
    a.join(); b.join();
    cout << "after two withdraw(80) = " << balance << " (should never be negative)\n";
    // Fix: hold the lock across check AND act
    balance = 100;
    auto safe = [&](int amt) {
        lock_guard<mutex> g(m);
        if (balance >= amt) balance -= amt;
    };
    thread c(safe, 80), d(safe, 80);
    c.join(); d.join();
    cout << "fixed version = " << balance << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// join() waits; jthread joins automatically in its destructor.
int main() {
    int result = 0;
    thread t([&] { result = 42; });
    cout << "joinable before join: " << boolalpha << t.joinable() << "\n";
    t.join();                          // wait; result is now visible
    cout << "joinable after join: " << t.joinable() << ", result = " << result << "\n";

    int total = 0;
    {
        // std::jthread: destructor calls request_stop() then join()
        jthread j([&](stop_token st) {
            for (int i = 1; i <= 5; i++) total += i;
            cout << "stop requested inside? " << st.stop_requested() << "\n";
        });
    }                                  // joined here, no terminate
    cout << "total after jthread scope = " << total << "\n";
    // A std::thread destroyed while joinable calls std::terminate,
    // so never let one leave scope without join() or detach().
}

