int main() {
    mutex m1, m2;
    int a = 0, b = 0;
    // scoped_lock: locks several mutexes with deadlock avoidance,
    // so opposite argument order in two threads is safe.
    auto f1 = [&] { for (int i = 0; i < 1000; i++) { scoped_lock l(m1, m2); a++; b++; } };
    auto f2 = [&] { for (int i = 0; i < 1000; i++) { scoped_lock l(m2, m1); a++; b++; } };
    thread t1(f1), t2(f2);
    t1.join(); t2.join();
    cout << "a=" << a << " b=" << b << " (expected 2000 each)\n";

    // lock_guard: simplest RAII lock
    { lock_guard<mutex> g(m1); a = 0; }
    // unique_lock: can defer, unlock early and re-lock
    unique_lock<mutex> u(m1, defer_lock);
    cout << "owns before lock: " << boolalpha << u.owns_lock() << "\n";
    u.lock();
    a = 10;
    u.unlock();                        // release early to do slow work
    cout << "owns after unlock: " << u.owns_lock() << ", a=" << a << "\n";
    u.lock();
    cout << "owns after relock: " << u.owns_lock() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Prevent deadlock with a global lock order (lock the lower id first).
struct Account { int id; long bal; mutex m; };
void transfer(Account& from, Account& to, long amt) {
    Account& first = from.id < to.id ? from : to;   // fixed ordering
    Account& second = from.id < to.id ? to : from;
    lock_guard<mutex> l1(first.m);
    lock_guard<mutex> l2(second.m);
    from.bal -= amt;
    to.bal += amt;
}
int main() {
    Account x{1, 1000}, y{2, 1000};
    // Opposite directions at the same time: with naive ordering
    // (lock "from" then "to") this can deadlock.
    thread t1([&] { for (int i = 0; i < 5000; i++) transfer(x, y, 1); });
    thread t2([&] { for (int i = 0; i < 5000; i++) transfer(y, x, 2); });
    t1.join(); t2.join();
    cout << "x=" << x.bal << " y=" << y.bal << " total=" << x.bal + y.bal << "\n";
    // Alternative: std::scoped_lock(first.m, second.m) does it for you.
    // Recovery style: try_lock with back-off
    mutex m;
    m.lock();
    thread t3([&] { cout << "try_lock while held: " << boolalpha << m.try_lock() << "\n"; });
    t3.join();
    m.unlock();
}

#include <bits/stdc++.h>
using namespace std;
// condition_variable: always wait with a predicate on shared state.
int main() {
    mutex m;
    condition_variable cv;
    queue<int> q;
    bool done = false;
    long sum = 0;
    thread consumer([&] {
        unique_lock<mutex> lk(m);
        while (true) {
            // wait releases the lock, sleeps, re-locks, re-checks predicate
            cv.wait(lk, [&] { return !q.empty() || done; });
            while (!q.empty()) { sum += q.front(); q.pop(); }
            if (done) break;
        }
    });
    for (int i = 1; i <= 10; i++) {
        { lock_guard<mutex> g(m); q.push(i); }   // change state under the mutex
        cv.notify_one();                         // then notify
    }
    { lock_guard<mutex> g(m); done = true; }
    cv.notify_all();
    consumer.join();
    cout << "sum of 1..10 consumed = " << sum << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Bounded blocking queue with a close() for clean shutdown.
template <class T> class BQ {
    mutex m; condition_variable notFull, notEmpty;
    deque<T> d; size_t cap; bool closed = false;
public:
    BQ(size_t c) : cap(c) {}
    bool push(T v) {
        unique_lock<mutex> lk(m);
        notFull.wait(lk, [&] { return d.size() < cap || closed; });
        if (closed) return false;
        d.push_back(move(v));
        notEmpty.notify_one();
        return true;
    }
    optional<T> pop() {
        unique_lock<mutex> lk(m);
        notEmpty.wait(lk, [&] { return !d.empty() || closed; });
        if (d.empty()) return nullopt;           // closed and drained
        T v = move(d.front()); d.pop_front();
        notFull.notify_one();
        return v;
    }
    void close() { { lock_guard<mutex> g(m); closed = true; } notFull.notify_all(); notEmpty.notify_all(); }
};
int main() {
    BQ<int> q(3);
    long sum = 0;
    thread cons([&] { while (auto v = q.pop()) sum += *v; });
    for (int i = 1; i <= 100; i++) q.push(i);    // blocks when 3 items are queued
    q.close();
    cons.join();
    cout << "capacity 3, sum of 1..100 = " << sum << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Atomic for one variable; mutex when an invariant spans several.
int main() {
    atomic<int> hits{0};
    int plain = 0;
    mutex m;
    vector<thread> ts;
    for (int t = 0; t < 4; t++)
        ts.emplace_back([&] {
            for (int i = 0; i < 10000; i++) {
                hits.fetch_add(1, memory_order_relaxed);  // fine: single counter
                lock_guard<mutex> g(m); plain++;
            }
        });
    for (auto& t : ts) t.join();
    cout << "atomic counter = " << hits << ", mutex counter = " << plain << "\n";

    // Two fields that must change together: atomics per field are NOT enough.
    struct Stats { long count = 0; long sum = 0; } s;   // invariant: sum == 2*count
    vector<thread> w;
    for (int t = 0; t < 4; t++)
        w.emplace_back([&] { for (int i = 0; i < 1000; i++) { lock_guard<mutex> g(m); s.count++; s.sum += 2; } });
    for (auto& t : w) t.join();
    cout << "count=" << s.count << " sum=" << s.sum << " invariant ok: " << boolalpha << (s.sum == 2 * s.count) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// CAS loop: lock-free "atomic max".
void atomicMax(atomic<int>& x, int v) {
    int cur = x.load();
    // On failure compare_exchange_weak refreshes cur, so we just retry.
    while (cur < v && !x.compare_exchange_weak(cur, v)) {}
}
int main() {
    atomic<int> best{0};
    vector<thread> ts;
    for (int t = 0; t < 4; t++)
        ts.emplace_back([&, t] {
            for (int i = 0; i < 1000; i++) atomicMax(best, t * 1000 + i);
        });
    for (auto& t : ts) t.join();
    cout << "max over all threads = " << best << " (expected 3999)\n";

    // strong CAS: one-shot "claim" of a flag
    atomic<int> owner{0};
    int expected = 0;
    bool first = owner.compare_exchange_strong(expected, 7);
    expected = 0;
    bool second = owner.compare_exchange_strong(expected, 9);
    cout << boolalpha << "first claim " << first << ", second claim " << second
         << " (owner now " << owner << ", expected refreshed to " << expected << ")\n";
}

#include <bits/stdc++.h>
using namespace std;
// release/acquire publishes plain payload; relaxed is fine for a pure counter.
int payload = 0;
atomic<bool> ready{false};
atomic<int> hits{0};
int main() {
    thread producer([] {
        payload = 42;                                   // plain write
        ready.store(true, memory_order_release);     // publish everything above
    });
    thread consumer([] {
        while (!ready.load(memory_order_acquire)) {} // sees release store
        cout << "consumer sees payload = " << payload << "\n"; // guaranteed 42
    });
    producer.join(); consumer.join();

    vector<thread> ts;
    for (int i = 0; i < 4; i++)
        ts.emplace_back([] { for (int j = 0; j < 1000; j++) hits.fetch_add(1, memory_order_relaxed); });
    for (auto& t : ts) t.join();   // join gives the ordering for the final read
    cout << "relaxed counter = " << hits.load(memory_order_relaxed) << "\n";
    // seq_cst (the default) is needed when each thread stores its own flag then
    // reads the other's (Dekker/Peterson); acquire/release alone allows both to read 0.
}

#include <bits/stdc++.h>
using namespace std;
// Happens-before edges: thread start, join, mutex, promise/future.
int main() {
    int a = 1;                                  // written before thread creation
    int b = 0;
    thread t([&] { cout << "child sees a = " << a << "\n"; b = a + 1; });
    t.join();                                   // thread end happens-before join returns
    cout << "after join b = " << b << "\n";

    promise<int> p;
    future<int> f = p.get_future();
    int payload = 0;
    thread t2([&] { payload = 99; p.set_value(1); });  // set_value -> get
    f.get();
    cout << "after future.get payload = " << payload << "\n";

    mutex m; int shared = 0;
    thread t3([&] { lock_guard<mutex> g(m); shared = 5; });
    t3.join();
    { lock_guard<mutex> g(m); cout << "after unlock/lock shared = " << shared << "\n"; }
    t2.join();
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    auto me = this_thread::get_id();
    auto fa = async(launch::async, [] { return this_thread::get_id(); });
    auto fd = async(launch::deferred, [] { return this_thread::get_id(); });
    cout << boolalpha;
    cout << "async runs on another thread: " << (fa.get() != me) << "\n";
    // deferred does not run until get(), and then on the calling thread
    cout << "wait_for on deferred returns deferred: "
         << (fd.wait_for(0ms) == future_status::deferred) << "\n";
    cout << "deferred runs on caller thread: " << (fd.get() == me) << "\n";

    // Gotcha: discarded future blocks in its destructor
    auto start = chrono::steady_clock::now();
    (void)async(launch::async, [] { this_thread::sleep_for(100ms); });  // temp future destroyed here
    auto ms = chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - start).count();
    cout << "discarded async blocked at least 100ms: " << (ms >= 100) << "\n";

    // Exceptions travel through the future
    auto fe = async(launch::async, []() -> int { throw runtime_error("boom"); });
    try { fe.get(); } catch (const exception& e) { cout << "caught: " << e.what() << "\n"; }
}

#include <bits/stdc++.h>
using namespace std;
class Pool {
    vector<thread> workers; queue<function<void()>> jobs;
    mutex m; condition_variable cv; bool stopping = false;
public:
    Pool(int n) {
        for (int i = 0; i < n; i++) workers.emplace_back([this] {
            while (true) {
                function<void()> job;
                { unique_lock<mutex> lk(m);
                  cv.wait(lk, [this] { return stopping || !jobs.empty(); });
                  if (jobs.empty()) return;          // stopping and drained
                  job = move(jobs.front()); jobs.pop(); }
                job();                               // run OUTSIDE the lock
            }
        });
    }
    template <class F> auto submit(F f) {
        using R = invoke_result_t<F>;
        auto task = make_shared<packaged_task<R()>>(move(f));
        auto fut = task->get_future();               // result or exception
        { lock_guard<mutex> g(m); if (stopping) throw runtime_error("pool stopped");
          jobs.push([task] { (*task)(); }); }
        cv.notify_one();
        return fut;
    }
    ~Pool() {
        { lock_guard<mutex> g(m); stopping = true; }
        cv.notify_all();
        for (auto& w : workers) w.join();            // drains the queue first
    }
};
int main() {
    vector<future<int>> fs;
    {
        Pool pool(3);
        for (int i = 1; i <= 5; i++) fs.push_back(pool.submit([i] { return i * i; }));
    }                                                // shutdown here
    for (auto& f : fs) cout << f.get() << " ";
    cout << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Publish an immutable config snapshot with atomic<shared_ptr>.
struct Config { int version; string name; };
atomic<shared_ptr<Config>> current;
int main() {
    current.store(make_shared<Config>(Config{1, "alpha"}));
    atomic<bool> stop{false};
    atomic<int> reads{0};
    thread reader([&] {
        while (!stop) {
            shared_ptr<Config> snap = current.load();   // safe copy, keeps it alive
            if (snap->name.empty()) abort();
            reads++;
        }
    });
    for (int v = 2; v <= 5; v++)                         // writer replaces whole object
        current.store(make_shared<Config>(Config{v, "cfg" + to_string(v)}));
    stop = true; reader.join();
    auto last = current.load();
    cout << "final version " << last->version << " name " << last->name << "\n";
    // the control block counts are atomic: copies across threads are safe
    auto sp = make_shared<int>(7);
    thread t1([sp] { auto c = sp; }), t2([sp] { auto c = sp; });
    t1.join(); t2.join();
    cout << "use_count after threads finished = " << sp.use_count() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Stress test: many threads, many iterations, check an invariant at the end.
// Build also with: g++ -std=c++20 -fsanitize=thread -g main.cpp
struct Counter {
    mutex m; long n = 0;
    void inc() { lock_guard<mutex> g(m); n++; }
};
int main() {
    int bad = 0;
    for (int round = 0; round < 50; round++) {
        Counter c;
        int threads = 16;                            // more threads than cores
        vector<thread> ts;
        for (int t = 0; t < threads; t++)
            ts.emplace_back([&] {
                for (int i = 0; i < 1000; i++) {
                    c.inc();
                    if (i % 100 == 0) this_thread::yield();  // perturb timing
                }
            });
        for (auto& t : ts) t.join();
        if (c.n != 16000) bad++;
    }
    cout << "rounds with wrong total: " << bad << " of 50\n";
}
